import React from 'react';
import { Cpu, ChevronRight, Activity } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const FactoryDigitalTwinGrid = ({ machines = [] }) => {
  const navigate = useNavigate();

  // Clean Machine overview list
  const displayMachines = machines.length > 0 ? machines : [
    { machineId: 'LOOM-101', name: 'Toyota Air Jet Alpha', currentStatus: 'RUNNING', healthScore: 96 },
    { machineId: 'LOOM-102', name: 'Picanol Rapier Beta', currentStatus: 'RUNNING', healthScore: 94 },
    { machineId: 'LOOM-201', name: 'Dornier Heavy Shuttleless', currentStatus: 'MAINTENANCE', healthScore: 68 },
    { machineId: 'LOOM-301', name: 'Itema A9500 Denim', currentStatus: 'RUNNING', healthScore: 98 },
    { machineId: 'LOOM-401', name: 'Tsudakoma Water Jet', currentStatus: 'IDLE', healthScore: 88 },
    { machineId: 'LOOM-501', name: 'Picanol OmniPlus i', currentStatus: 'RUNNING', healthScore: 97 },
  ];

  const getStatusBadge = (status) => {
    const s = (status || '').toUpperCase();
    if (s === 'RUNNING') {
      return { bg: '#DCFCE7', color: '#166534', label: 'RUNNING', dot: '#22C55E' };
    }
    if (s === 'IDLE') {
      return { bg: '#FEF3C7', color: '#92400E', label: 'IDLE', dot: '#F59E0B' };
    }
    return { bg: '#FEE2E2', color: '#991B1B', label: 'MAINTENANCE', dot: '#EF4444' };
  };

  return (
    <div
      style={{
        background: '#ffffff',
        borderRadius: '8px',
        padding: '1.25rem 1.5rem',
        border: '1px solid #E2E8F0',
        boxShadow: '0 2px 10px rgba(0, 0, 0, 0.04)',
        height: '100%',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between',
      }}
    >
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
        <div>
          <h3 style={{ fontSize: '1.05rem', fontWeight: '900', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.45rem' }}>
            <Cpu size={18} style={{ color: '#2563EB' }} /> Factory Digital Twin Overview
          </h3>
          <p style={{ fontSize: '0.76rem', color: '#64748B', fontWeight: '600', marginTop: '2px' }}>
            Real-time machine mirroring and operational status across active looms
          </p>
        </div>

        <button
          className="btn btn-secondary btn-sm"
          onClick={() => navigate('/digital-twin')}
          style={{ fontSize: '0.78rem', fontWeight: '800', padding: '0.35rem 0.75rem', background: '#F8FAFC' }}
        >
          Explore All Twins →
        </button>
      </div>

      {/* Grid of Clean Machine Cards */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
          gap: '1rem',
        }}
      >
        {displayMachines.map((m) => {
          const st = getStatusBadge(m.currentStatus);
          return (
            <div
              key={m.machineId || m.id}
              onClick={() => navigate('/digital-twin')}
              style={{
                background: '#F8FAFC',
                borderRadius: '8px',
                padding: '1rem',
                border: '1px solid #E2E8F0',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between',
                boxShadow: '0 1px 4px rgba(0,0,0,0.02)',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-2px)';
                e.currentTarget.style.borderColor = '#2563EB';
                e.currentTarget.style.boxShadow = '0 4px 12px rgba(37, 99, 235, 0.12)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'none';
                e.currentTarget.style.borderColor = '#E2E8F0';
                e.currentTarget.style.boxShadow = '0 1px 4px rgba(0,0,0,0.02)';
              }}
            >
              {/* Card Header: Machine ID & Status */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                <span style={{ fontSize: '0.78rem', fontWeight: '900', color: '#2563EB', fontFamily: 'JetBrains Mono, monospace' }}>
                  {m.machineId}
                </span>

                <span
                  style={{
                    background: st.bg,
                    color: st.color,
                    padding: '0.15rem 0.5rem',
                    borderRadius: '12px',
                    fontSize: '0.66rem',
                    fontWeight: '800',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.3rem',
                  }}
                >
                  <span style={{ width: '5px', height: '5px', borderRadius: '50%', background: st.dot }} />
                  {st.label}
                </span>
              </div>

              {/* Machine Name */}
              <div style={{ fontSize: '0.9rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.65rem' }}>
                {m.name || m.assetName}
              </div>

              {/* Health Score & Action Button */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '0.5rem', borderTop: '1px solid #E2E8F0' }}>
                <div>
                  <div style={{ fontSize: '0.66rem', color: '#64748B', fontWeight: '700' }}>HEALTH SCORE</div>
                  <div style={{ fontSize: '0.95rem', fontWeight: '900', color: (m.healthScore || 96) < 75 ? '#DC2626' : '#16A34A' }}>
                    {m.healthScore || 96}%
                  </div>
                </div>

                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    navigate('/digital-twin');
                  }}
                  style={{
                    background: '#2563EB',
                    color: '#ffffff',
                    border: 'none',
                    borderRadius: '6px',
                    padding: '0.3rem 0.65rem',
                    fontSize: '0.72rem',
                    fontWeight: '800',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.2rem',
                    cursor: 'pointer',
                  }}
                >
                  View Twin <ChevronRight size={12} />
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default FactoryDigitalTwinGrid;
